use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 8;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

fn cell(x: i32, y: i32) -> u32 {
    if (x < 0 || y < 0 || x >= i32(dims.width) || y >= i32(dims.height)) {
        return 0u;
    }
    return src[u32(y) * dims.width + u32(x)];
}

@compute @workgroup_size(8, 8, 1)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= dims.width || id.y >= dims.height) {
        return;
    }
    let x = i32(id.x);
    let y = i32(id.y);
    let n = cell(x - 1, y - 1) + cell(x, y - 1) + cell(x + 1, y - 1)
          + cell(x - 1, y)                      + cell(x + 1, y)
          + cell(x - 1, y + 1) + cell(x, y + 1) + cell(x + 1, y + 1);
    let alive = cell(x, y);
    var next = 0u;
    if (n == 3u || (alive == 1u && n == 2u)) {
        next = 1u;
    }
    dst[id.y * dims.width + id.x] = next;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    generations: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_whitespace();
    let mut header = |name: &str, lo: u32, hi: u32| -> Result<u32, String> {
        let tok = tokens.next().ok_or_else(|| format!("missing {name}"))?;
        let v: u32 = tok
            .parse()
            .map_err(|_| format!("invalid {name}: {tok:?}"))?;
        if v < lo || v > hi {
            return Err(format!("{name} {v} out of range {lo}..={hi}"));
        }
        Ok(v)
    };
    let width = header("width", 1, 512)?;
    let height = header("height", 1, 512)?;
    let generations = header("generations", 0, 1000)?;

    let count = (width * height) as usize;
    let mut cells = Vec::with_capacity(count);
    for tok in tokens {
        if cells.len() == count {
            return Err("too many cells in input".into());
        }
        match tok {
            "0" => cells.push(0),
            "1" => cells.push(1),
            _ => return Err(format!("invalid cell {tok:?}")),
        }
    }
    if cells.len() != count {
        return Err(format!(
            "expected {count} cells, found {}",
            cells.len()
        ));
    }
    Ok(Grid {
        width,
        height,
        generations,
        cells,
    })
}

async fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = match instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
    {
        Ok(a) => a,
        Err(_) => instance
            .request_adapter(&wgpu::RequestAdapterOptions {
                force_fallback_adapter: true,
                ..Default::default()
            })
            .await
            .map_err(|e| format!("no GPU adapter available: {e}"))?,
    };
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor {
            label: Some("life"),
            required_features: wgpu::Features::empty(),
            required_limits: wgpu::Limits::downlevel_defaults().using_resolution(adapter.limits()),
            ..Default::default()
        })
        .await
        .map_err(|e| format!("failed to create device: {e}"))?;

    let size = (grid.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let dims = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&[grid.width, grid.height]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let storage_usage =
        wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buffers = [
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("cells-a"),
            contents: bytemuck::cast_slice(&grid.cells),
            usage: storage_usage,
        }),
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("cells-b"),
            size,
            usage: storage_usage,
            mapped_at_creation: false,
        }),
    ];
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("life"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("life"),
        layout: None,
        module: &module,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    // bind_groups[i] reads buffers[i] and writes buffers[1 - i].
    let bind_groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("life"),
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: dims.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: buffers[i].as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: buffers[1 - i].as_entire_binding(),
                    },
                ],
            })
        })
        .collect();

    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&Default::default());
    for g in 0..grid.generations {
        // Separate passes so each generation sees the previous one's writes.
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[(g % 2) as usize], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    let result = &buffers[(grid.generations % 2) as usize];
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::Wait)
        .map_err(|e| format!("device poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback dropped: {e}"))?
        .map_err(|e| format!("failed to map readback buffer: {e}"))?;
    let cells = bytemuck::cast_slice::<u8, u32>(&slice.get_mapped_range()).to_vec();
    readback.unmap();
    Ok(cells)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: gpu-life <input-file>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {}: {e}", path.to_string_lossy());
            return ExitCode::from(1);
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("invalid input: {e}");
            return ExitCode::from(1);
        }
    };
    let cells = match pollster::block_on(run_gpu(&grid)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{e}");
            return ExitCode::from(1);
        }
    };

    let width = grid.width as usize;
    let mut out = String::with_capacity(cells.len() * 2 + 32);
    for row in cells.chunks(width) {
        for (i, &c) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            out.push(if c != 0 { '1' } else { '0' });
        }
        out.push('\n');
    }
    let alive = cells.iter().filter(|&&c| c != 0).count();
    out.push_str(&format!("ALIVE {alive}\n"));

    use std::io::Write;
    let mut stdout = std::io::stdout().lock();
    if stdout.write_all(out.as_bytes()).and_then(|_| stdout.flush()).is_err() {
        return ExitCode::from(1);
    }
    ExitCode::SUCCESS
}
